parameters.jsCode:
const events = $('Webhook').first()?.json?.body?.events || [];
const firstEvent = events[0] || {};
const rawText = firstEvent?.message?.text || '';
const userText = rawText.trim();
const search = userText.toLowerCase();

// 🔒 ล็อกคำสั่งระบบ
const systemCommands = ['เมนูหลัก', 'จองตั๋ว', 'บริษัทขนส่ง'];
if (!userText || systemCommands.includes(userText)) {
  return [];
}

// 🔍 ค้นหาแถวที่ตรงกับคำค้นหา
const matchedRow = $input.all().find(item => {
  const row = item.json;
  const keywords = (row.Keywords || '').split(',').map(k => k.trim().toLowerCase());
  const destination = (row.Destination || '').toLowerCase();
  const company = (row.Company || '').toLowerCase();

  return keywords.some(k => k && (search.includes(k) || k.includes(search))) || 
         (destination && search.includes(destination)) ||
         (company && (search.includes(company) || company.includes(search)));
});

if (matchedRow && matchedRow.json.Image_URL) {
  const row = matchedRow.json;

  // ⏱️ คำนวณเวลากรุงเทพฯ ปัจจุบัน
  const now = new Date(new Date().toLocaleString("en-US", { timeZone: "Asia/Bangkok" }));
  const currentMinutes = now.getHours() * 60 + now.getMinutes();

  // ดึงรอบเวลาจากคอลัมน์ Departure_Times
  const timesStr = row.Departure_Times || '';
  const timeList = timesStr.split(',').map(t => t.trim()).filter(t => t);

  let nextBus = null;
  let minutesLeft = 0;

  for (const t of timeList) {
    const parts = t.split(':');
    if (parts.length === 2) {
      const busMinutes = parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);
      if (busMinutes > currentMinutes) {
        nextBus = t;
        minutesLeft = busMinutes - currentMinutes;
        break;
      }
    }
  }

  // สร้างข้อความสรุปรอบรถ
  let alertMessage = '';
  if (nextBus) {
    const hours = Math.floor(minutesLeft / 60);
    const mins = minutesLeft % 60;
    const timeText = hours > 0 ? `${hours} ชม. ${mins} นาที` : `${mins} นาที`;
    alertMessage = `⏰ รอบถัดไป: ${nextBus} น. (เหลือเวลาเดินทางไป บขส. อีก ${timeText})`;
  } else if (timeList.length > 0) {
    alertMessage = `🌙 รอบรถวันนี้หมดแล้ว (รอบแรกพรุ่งนี้: ${timeList[0]} น.)`;
  } else {
    alertMessage = `ℹ️ ตรวจสอบเวลาเดินรถตามตารางในรูปภาพ`;
  }

  return [{
    json: {
      ...row,
      Next_Bus_Alert: alertMessage
    }
  }];
} else {
  return [{ json: { Image_URL: '' } }];
}

